void vMainTask(void *pvParameters) {
    // Wait for all subsystems ready
    xEventGroupWaitBits(xSystemEvents, EVENT_ALL_READY, pdFALSE, pdTRUE, portMAX_DELAY);

    // System fully initialized
    for (;;) {
        RunMainLoop();
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}
