  9	#include "velawear_agent_protocol.h"
 10	
 11	static bool velawear_agent_command_is_known(uint8_t command_id)
 12	{
 13	  return command_id == VELAWEAR_AGENT_COMMAND_ACK_ALERT ||
 14	         command_id == VELAWEAR_AGENT_COMMAND_SET_SEDENTARY_THRESHOLD ||
 15	         command_id == VELAWEAR_AGENT_COMMAND_SHOW_REMINDER;
 16	}
 17	
 18	static bool velawear_agent_command_is_valid(uint8_t command_id,
 19	                                            uint16_t argument)
 20	{
 21	  if (!velawear_agent_command_is_known(command_id))
 22	    {
 23	      return false;
 24	    }
 25	
 26	  switch (command_id)
 27	    {
 28	      case VELAWEAR_AGENT_COMMAND_ACK_ALERT:
 29	        return argument == 0;
 30	
 31	      case VELAWEAR_AGENT_COMMAND_SET_SEDENTARY_THRESHOLD:
 32	        return argument >= 10 && argument <= 3600;
 33	
 34	      case VELAWEAR_AGENT_COMMAND_SHOW_REMINDER:
 35	        return argument <= VELAWEAR_AGENT_REMINDER_REST;
 36	
 37	      default:
 38	        return false;
 39	    }
 40	}
 41	
 42	int velawear_agent_encode_event(const velawear_agent_event_t *event,
 43	                                uint8_t *frame, uint16_t frame_size)
 44	{
 45	  if (event == NULL || frame == NULL ||
 46	      frame_size < VELAWEAR_AGENT_EVENT_FRAME_SIZE)
 47	    {
 48	      return -EINVAL;
 49	    }
 50	
 51	  frame[0] = VELAWEAR_AGENT_PROTOCOL_VERSION;
 52	  frame[1] = event->event_type;
 53	  frame[2] = (uint8_t)(event->sequence & 0xff);
 54	  frame[3] = (uint8_t)(event->sequence >> 8);
 55	  frame[4] = event->priority;
 56	  frame[5] = event->intensity_percent;
 57	  frame[6] = (uint8_t)(event->value & 0xff);
 58	  frame[7] = (uint8_t)(event->value >> 8);
 59	  frame[8] = (uint8_t)(event->peak & 0xff);
 60	  frame[9] = (uint8_t)(event->peak >> 8);
 61	  frame[10] = event->flags;
 62	  return VELAWEAR_AGENT_EVENT_FRAME_SIZE;
 63	}
 64	
 65	int velawear_agent_decode_command(const uint8_t *frame, uint16_t frame_size,
 66	                                  velawear_agent_command_t *command)
 67	{
 68	  uint8_t command_id;
 69	  uint16_t argument;
 70	
 71	  if (frame == NULL || command == NULL ||
 72	      frame_size != VELAWEAR_AGENT_COMMAND_FRAME_SIZE ||
 73	      frame[0] != VELAWEAR_AGENT_PROTOCOL_VERSION)
 74	    {
 75	      return -EINVAL;
 76	    }
 77	
 78	  command_id = frame[1];
 79	  argument = (uint16_t)frame[4] | ((uint16_t)frame[5] << 8);
 80	  if (!velawear_agent_command_is_valid(command_id, argument))
 81	    {
 82	      return -EINVAL;
 83	    }
 84	
 85	  command->sequence = (uint16_t)frame[2] | ((uint16_t)frame[3] << 8);
 86	  command->command_id = command_id;
 87	  command->argument = argument;
 88	  return 0;
 89	}
 90	
 91	int velawear_agent_encode_command_result(uint16_t sequence, uint8_t command_id,
 92	                                         uint8_t result, uint8_t *frame,
 93	                                         uint16_t frame_size)
 94	{
 95	  if (frame == NULL || frame_size < VELAWEAR_AGENT_RESULT_FRAME_SIZE ||
 96	      !velawear_agent_command_is_known(command_id) ||
 97	      result > VELAWEAR_AGENT_COMMAND_RESULT_EXECUTION_FAILED)
 98	    {
 99	      return -EINVAL;
100	    }
101	
102	  frame[0] = VELAWEAR_AGENT_PROTOCOL_VERSION;
103	  frame[1] = command_id;
104	  frame[2] = (uint8_t)(sequence & 0xff);
105	  frame[3] = (uint8_t)(sequence >> 8);
106	  frame[4] = result;
107	  return VELAWEAR_AGENT_RESULT_FRAME_SIZE;
108	}
109	
110	int velawear_agent_encode_llm_request(uint16_t sequence,
111	                                      const char *prompt,
112	                                      uint8_t *frame, uint16_t frame_size)
113	{
114	  size_t length;
115	
116	  if (prompt == NULL || frame == NULL)
117	    {
118	      return -EINVAL;
119	    }
120	
121	  length = strlen(prompt);
122	  if (length > VELAWEAR_AGENT_LLM_TEXT_MAX ||
123	      frame_size < VELAWEAR_AGENT_LLM_REQUEST_HEADER_SIZE + length)
124	    {
125	      return -EMSGSIZE;
126	    }
127	
128	  frame[0] = VELAWEAR_AGENT_PROTOCOL_VERSION;
129	  frame[1] = VELAWEAR_AGENT_LLM_REQUEST_TYPE;
130	  frame[2] = (uint8_t)(sequence & 0xff);
131	  frame[3] = (uint8_t)(sequence >> 8);
132	  frame[4] = (uint8_t)(length & 0xff);
133	  frame[5] = (uint8_t)(length >> 8);
134	  memcpy(frame + VELAWEAR_AGENT_LLM_REQUEST_HEADER_SIZE, prompt, length);
135	  return VELAWEAR_AGENT_LLM_REQUEST_HEADER_SIZE + (int)length;
136	}
137	
138	int velawear_agent_decode_llm_response(const uint8_t *frame,
139	                                      uint16_t frame_size,
140	                                      velawear_agent_llm_response_t *response)
141	{
142	  uint16_t length;
143	  uint16_t expected_size;
144	
145	  if (frame == NULL || response == NULL ||
146	      frame_size < VELAWEAR_AGENT_LLM_RESPONSE_HEADER_SIZE ||
147	      frame[0] != VELAWEAR_AGENT_PROTOCOL_VERSION ||
148	      frame[1] != VELAWEAR_AGENT_LLM_RESPONSE_TYPE)
149	    {
150	      return -EINVAL;
151	    }
152	
153	  length = (uint16_t)frame[5] | ((uint16_t)frame[6] << 8);
154	  if (length > VELAWEAR_AGENT_LLM_TEXT_MAX ||
155	      frame[4] > VELAWEAR_AGENT_LLM_STATUS_ERROR)
156	    {
157	      return -EINVAL;
158	    }
159	
160	  expected_size = (uint16_t)(VELAWEAR_AGENT_LLM_RESPONSE_HEADER_SIZE + length);
161	  if (frame_size != expected_size)
162	    {
163	      return -EINVAL;
164	    }
165	
166	  memset(response, 0, sizeof(*response));
167	  response->sequence = (uint16_t)frame[2] | ((uint16_t)frame[3] << 8);
168	  response->status = frame[4];
169	  response->length = length;
170	  memcpy(response->text, frame + VELAWEAR_AGENT_LLM_RESPONSE_HEADER_SIZE,
171	         length);
172	  response->text[length] = '\0';
173	  return 0;
174	}
