283	uint32_t velawear_agent_crc32(const uint8_t *data, size_t length)
284	{
285	  uint32_t crc = UINT32_MAX;
286	
287	  if (data == NULL && length != 0)
288	    {
289	      return 0;
290	    }
291	
292	  for (size_t i = 0; i < length; i++)
293	    {
294	      crc ^= data[i];
295	      for (uint8_t bit = 0; bit < 8; bit++)
296	        {
297	          crc = (crc & 1U) != 0 ? (crc >> 1) ^ 0xedb88320U : crc >> 1;
298	        }
299	    }
300	
301	  return crc ^ UINT32_MAX;
302	}
