304	int velawear_agent_encode_message(uint16_t sequence, uint8_t priority,
305	                                  const char *text, uint8_t *frame,
306	                                  uint16_t frame_size)
307	{
308	  size_t length;
309	
310	  if (text == NULL || frame == NULL)
311	    {
312	      return -EINVAL;
313	    }
314	
315	  length = strlen(text);
316	  if (length > VELAWEAR_AGENT_MESSAGE_TEXT_MAX ||
317	      frame_size < VELAWEAR_AGENT_MESSAGE_HEADER_SIZE + length)
318	    {
319	      return -EMSGSIZE;
320	    }
321	
322	  frame[0] = VELAWEAR_AGENT_PROTOCOL_VERSION;
323	  frame[1] = VELAWEAR_AGENT_MESSAGE_TYPE;
324	  frame[2] = (uint8_t)(sequence & 0xff);
325	  frame[3] = (uint8_t)(sequence >> 8);
326	  frame[4] = priority;
327	  frame[5] = (uint8_t)(length & 0xff);
328	  frame[6] = (uint8_t)(length >> 8);
329	  memcpy(frame + VELAWEAR_AGENT_MESSAGE_HEADER_SIZE, text, length);
330	  return VELAWEAR_AGENT_MESSAGE_HEADER_SIZE + (int)length;
331	}
