333	bool velawear_agent_command_sequence_is_newer(uint16_t candidate,
334	                                              uint16_t previous)
335	{
336	  uint16_t distance = (uint16_t)(candidate - previous);
337	
338	  return distance != 0 && distance < 0x8000;
339	}

