334	  velawear_event_t event;
335	  int ret;
336	
337	  (void)conn;
338	  (void)attr;
339	  if (buf == NULL || offset != 0 ||
340	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
341	      velawear_agent_decode_command(data, len, &command) < 0)
342	    {
343	      return -EINVAL;
344	    }
345	
346	  pthread_mutex_lock(&g_lock);
347	  if (g_events == NULL ||
348	      (g_have_last_agent_command_sequence &&
349	       !velawear_agent_command_sequence_is_newer(
350	           command.sequence, g_last_agent_command_sequence)))
351	    {
352	      pthread_mutex_unlock(&g_lock);
353	      return -EALREADY;
354	    }
355	
356	  g_last_agent_command_sequence = command.sequence;
357	  g_have_last_agent_command_sequence = true;
358	  pthread_mutex_unlock(&g_lock);
359	
360	  memset(&event, 0, sizeof(event));
361	  event.type = VELAWEAR_EVENT_BLE_MSG;
362	  event.priority = VELAWEAR_PRIORITY_HIGH;
363	  event.data.ble.length = len;
364	  memcpy(event.data.ble.data, data, len);
365	  ret = event_manager_push(g_events, &event);
366	  if (ret < 0)
367	    {
368	      syslog(LOG_WARNING, "[BLE] Agent command queue full: %d\n", ret);
369	      return BT_GATT_ERR(BT_ATT_ERR_INSUFFICIENT_RESOURCES);
370	    }
371	
372	  syslog(LOG_INFO, "[BLE] Agent command queued: seq=%u id=%u\n",
373	         (unsigned int)command.sequence, (unsigned int)command.command_id);
374	  return len;
375	}
