377	static ssize_t velawear_ble_write_audio_stream(
378	    struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
379	    uint16_t len, uint16_t offset, uint8_t flags)
380	{
381	  const uint8_t *data = (const uint8_t *)buf;
382	  int ret;
383	
384	  (void)conn;
385	  (void)attr;
386	  if (buf == NULL || offset != 0 || len < 2 ||
387	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0)
388	    {
389	      return -EINVAL;
390	    }
391	
392	  switch (data[1])
393	    {
394	      case VELAWEAR_AGENT_AUDIO_START_TYPE:
395	        {
396	          velawear_agent_audio_start_t start;
397	
398	          if (velawear_agent_decode_audio_start(data, len, &start) < 0)
399	            {
400	              return -EINVAL;
401	            }
402	          ret = velawear_audio_voice_start(start.stream_id,
403	                                           start.sample_count,
404	                                           start.total_bytes,
405	                                           start.crc32);
406	          if (ret == 0)
407	            {
408	              syslog(LOG_INFO,
409	                     "[BLE] Audio stream start: id=%u samples=%lu bytes=%lu\n",
410	                     (unsigned int)start.stream_id,
411	                     (unsigned long)start.sample_count,
412	                     (unsigned long)start.total_bytes);
413	            }
414	        }
415	        break;
416	
417	      case VELAWEAR_AGENT_AUDIO_DATA_TYPE:
418	        {
419	          velawear_agent_audio_data_t audio_data;
420	
421	          if (velawear_agent_decode_audio_data(data, len, &audio_data) < 0)
422	            {
423	              return -EINVAL;
424	            }
425	          ret = velawear_audio_voice_write(audio_data.stream_id,
426	                                           audio_data.offset,
427	                                           audio_data.payload,
428	                                           audio_data.payload_length);
429	        }
430	        break;
431	
432	      case VELAWEAR_AGENT_AUDIO_END_TYPE:
433	        {
434	          velawear_agent_audio_end_t end;
435	          velawear_event_t event;
436	          uint32_t sample_count = 0;
437	
438	          if (velawear_agent_decode_audio_end(data, len, &end) < 0)
439	            {
440	              return -EINVAL;
441	            }
442	          ret = velawear_audio_voice_end(end.stream_id, end.total_bytes,
443	                                         end.crc32, &sample_count);
444	          if (ret == 0)
445	            {
446	              memset(&event, 0, sizeof(event));
447	              event.type = VELAWEAR_EVENT_VOICE_CMD;
448	              event.priority = VELAWEAR_PRIORITY_NORMAL;
449	              event.timestamp = k_uptime_get_32();
450	              event.data.voice.stream_id = end.stream_id;
451	              event.data.voice.sample_count = sample_count;
452	              ret = event_manager_push(g_events, &event);
453	              if (ret == 0)
454	                {
455	                  syslog(LOG_INFO,
456	                         "[BLE] Audio stream complete: id=%u samples=%lu\n",
457	                         (unsigned int)end.stream_id,
458	                         (unsigned long)sample_count);
459	                }
460	              else
461	                {
462	                  syslog(LOG_WARNING,
463	                         "[BLE] Audio voice event queue failed: %d\n", ret);
464	                }
465	            }
466	        }
467	        break;
468	
469	      default:
470	        return -EINVAL;
471	    }
472	
473	  if (ret < 0)
474	    {
475	      syslog(LOG_WARNING, "[BLE] Audio stream write rejected type=%u: %d\n",
476	             (unsigned int)data[1], ret);
477	      return BT_GATT_ERR(BT_ATT_ERR_UNLIKELY);
478	    }
479	
480	  return len;
481	}
