662	static uint8_t velawear_ble_percent_from_intensity(float intensity)
663	{
664	  if (intensity <= 0.0f)
665	    {
666	      return 0;
667	    }
668	
669	  if (intensity >= 1.0f)
670	    {
671	      return 100;
672	    }
673	
674	  return (uint8_t)(intensity * 100.0f);
675	}
