682	int velawear_ble_publish_agent_event(const velawear_event_t *event)
683	{
684	  velawear_agent_event_t agent_event;
685	  uint8_t frame[VELAWEAR_AGENT_EVENT_FRAME_SIZE];
686	  int ret;
687	
688	  if (event == NULL || !g_initialized)
689	    {
690	      return VELAWEAR_ERR_INVAL;
691	    }
692	
693	  memset(&agent_event, 0, sizeof(agent_event));
694	  switch (event->type)
695	    {
696	      case VELAWEAR_EVENT_MOTION:
697	        agent_event.event_type = VELAWEAR_AGENT_EVENT_MOTION;
698	        agent_event.intensity_percent =
699	            velawear_ble_percent_from_intensity(event->data.motion.intensity);
700	        break;
701	
702	      case VELAWEAR_EVENT_FALL:
703	        agent_event.event_type = VELAWEAR_AGENT_EVENT_FALL;
704	        agent_event.priority = VELAWEAR_AGENT_PRIORITY_CRITICAL;
705	        agent_event.intensity_percent = 100;
706	        break;
707	
708	      case VELAWEAR_EVENT_AUDIO:
709	        agent_event.event_type = VELAWEAR_AGENT_EVENT_AUDIO;
710	        agent_event.intensity_percent = event->data.audio.active ? 100 : 0;
711	        agent_event.value = velawear_ble_u16_saturate(event->data.audio.avg_abs);
712	        agent_event.peak = velawear_ble_u16_saturate(event->data.audio.peak_abs);
713	        if (event->data.audio.active)
714	          {
715	            agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ACTIVE;
716	          }
717	        break;
718	
719	      case VELAWEAR_EVENT_TIMER:
720	        agent_event.event_type = VELAWEAR_AGENT_EVENT_SEDENTARY;
721	        break;
722	
723	      default:
724	        return VELAWEAR_ERR_NOSUPPORT;
725	    }
726	
727	  pthread_mutex_lock(&g_lock);
728	  agent_event.sequence = g_agent_event_sequence++;
729	  if (g_alert_active)
730	    {
731	      agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ALERT;
732	    }
733	
734	  ret = velawear_agent_encode_event(&agent_event, frame, sizeof(frame));
735	  pthread_mutex_unlock(&g_lock);
736	  if (ret < 0)
737	    {
738	      return ret;
739	    }
740	
741	  return velawear_ble_notify_agent_packet(VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX,
742	                                          frame, (uint16_t)ret);
743	}
