794	int velawear_ble_request_llm(const char *prompt, char *response,
795	                              size_t response_size, uint32_t timeout_ms)
796	{
797	  uint8_t frame[VELAWEAR_AGENT_LLM_REQUEST_FRAME_MAX];
798	  struct bt_conn *conn;
799	  uint16_t sequence;
800	  uint16_t response_length;
801	  uint8_t response_status;
802	  size_t copy_length;
803	  int frame_size;
804	  int ret;
805	
806	  if (prompt == NULL || response == NULL || response_size == 0 ||
807	      timeout_ms == 0)
808	    {
809	      return -EINVAL;
810	    }
811	
812	  frame_size = velawear_agent_encode_llm_request(
813	      0, prompt, frame, sizeof(frame));
814	  if (frame_size < 0)
815	    {
816	      return frame_size;
817	    }
818	
819	  pthread_mutex_lock(&g_lock);
820	  if (!g_initialized || !g_llm_request_notify_enabled ||
821	      g_llm_request_notify_conn == NULL)
822	    {
823	      pthread_mutex_unlock(&g_lock);
824	      return -ENOTCONN;
825	    }
826	
827	  if (g_llm_waiting)
828	    {
829	      pthread_mutex_unlock(&g_lock);
830	      return -EBUSY;
831	    }
832	
833	  while (k_sem_take(&g_llm_response_sem, K_NO_WAIT) == 0)
834	    {
835	    }
836	
837	  sequence = g_llm_sequence++;
838	  if (g_llm_sequence == 0)
839	    {
840	      g_llm_sequence = 1;
841	    }
842	
843	  frame[2] = (uint8_t)(sequence & 0xff);
844	  frame[3] = (uint8_t)(sequence >> 8);
845	  g_llm_pending_sequence = sequence;
846	  g_llm_response_status = VELAWEAR_AGENT_LLM_STATUS_ERROR;
847	  g_llm_response_length = 0;
848	  g_llm_response_text[0] = '\0';
849	  g_llm_waiting = true;
850	  conn = bt_conn_ref(g_llm_request_notify_conn);
851	  pthread_mutex_unlock(&g_lock);
852	
853	  ret = bt_gatt_notify(conn,
854	                       &attr_velawear_svc[VELAWEAR_BLE_LLM_REQUEST_ATTR_INDEX],
855	                       frame, (uint16_t)frame_size);
856	  bt_conn_unref(conn);
857	  if (ret < 0)
858	    {
859	      pthread_mutex_lock(&g_lock);
860	      if (g_llm_pending_sequence == sequence)
861	        {
862	          g_llm_waiting = false;
863	        }
864	      pthread_mutex_unlock(&g_lock);
865	      syslog(LOG_WARNING, "[BLE] LLM request notify failed: %d\n", ret);
866	      return ret;
867	    }
868	
869	  ret = k_sem_take(&g_llm_response_sem, K_MSEC(timeout_ms));
870	  if (ret < 0)
871	    {
872	      pthread_mutex_lock(&g_lock);
873	      if (g_llm_pending_sequence == sequence)
874	        {
875	          g_llm_waiting = false;
876	        }
877	      pthread_mutex_unlock(&g_lock);
878	      syslog(LOG_WARNING, "[BLE] LLM response timeout: seq=%u\n",
879	             (unsigned int)sequence);
880	      return -ETIMEDOUT;
881	    }
882	
883	  pthread_mutex_lock(&g_lock);
884	  response_status = g_llm_response_status;
885	  response_length = g_llm_response_length;
886	  copy_length = response_length < response_size - 1 ?
887	                response_length : response_size - 1;
888	  memcpy(response, g_llm_response_text, copy_length);
889	  response[copy_length] = '\0';
890	  pthread_mutex_unlock(&g_lock);
891	
892	  if (response_status != VELAWEAR_AGENT_LLM_STATUS_OK)
893	    {
894	      return -EIO;
895	    }
896	
897	  return 0;
898	}
