   377	static void velawear_buttons_poll(velawear_display_t *display,
   378	                                  uint32_t *last_activity_ms)
   379	{
   380	  btn_buttonset_t sample;
   381	  ssize_t nbytes;
   382	  bool down;
   383	  uint32_t now;
   384	  uint32_t held_ms;
   385	
   386	  if (g_buttons_fd < 0)
   387	    {
   388	      return;
   389	    }
   390	
   391	  do
   392	    {
   393	      nbytes = read(g_buttons_fd, &sample, sizeof(sample));
   394	    }
   395	  while (nbytes < 0 && errno == EINTR);
   396	
   397	  if (nbytes != (ssize_t)sizeof(sample))
   398	    {
   399	      return;
   400	    }
   401	
   402	  down = (sample & VELAWEAR_KEY2_BIT) != 0;
   403	  now = velawear_now_ms();
   404	  if (down && !g_key2_down)
   405	    {
   406	      g_key2_down = true;
   407	      g_key2_down_ms = now;
   408	      if (last_activity_ms != NULL)
   409	        {
   410	          *last_activity_ms = now;
   411	        }
   412	      return;
   413	    }
   414	
   415	  if (!down && g_key2_down)
   416	    {
   417	      g_key2_down = false;
   418	      held_ms = now - g_key2_down_ms;
   419	      if (last_activity_ms != NULL)
   420	        {
   421	          *last_activity_ms = now;
   422	        }
   423	
   424	      if (display != NULL && display->initialized)
   425	        {
   426	          if (held_ms >= 1000 || display->detail_active ||
   427	              display->page_index == VELAWEAR_PAGE_APPS)
   428	            {
   429	              display_manager_close_app(display);
   430	              display_manager_set_page(display, VELAWEAR_PAGE_WATCHFACE);
   431	            }
   432	          else
   433	            {
   434	              display_manager_set_page(display, VELAWEAR_PAGE_WATCHFACE);
   435	            }
   436	          syslog(LOG_INFO, "[Buttons] KEY2 released held=%lu ms\n",
   437	                 (unsigned long)held_ms);
   438	        }
   439	    }
   440	}
