  1021	static int velawear_start(velawear_agent_t *agent)
  1022	{
  1023	  int ret;
  1024	
  1025	  /* The main loop owns event queue consumption.  Do not start a second
  1026	   * consumer thread for the same mqueue. */
  1027	
  1028	  /* Start action manager thread. */
  1029	
  1030	  ret = action_manager_start(&agent->actions);
  1031	  if (ret < 0)
  1032	    {
  1033	      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
  1034	      return ret;
  1035	    }
  1036	
  1037	  /* Decision rules use both event-driven evaluation and a real-state
  1038	   * periodic worker so inactivity can cross its threshold without another
  1039	   * motion edge. */
  1040	  agent->running = true;
  1041	  agent->started_ms = velawear_now_ms();
  1042	  ret = decision_engine_start(&agent->engine);
  1043	  if (ret < 0)
  1044	    {
  1045	      agent->running = false;
  1046	      syslog(LOG_ERR, "[VelaWear] Decision engine start failed: %d\n", ret);
  1047	      return ret;
  1048	    }
  1049	
  1050	  /* Mark agent as running before starting the sensor producer. */
  1051	
  1052	  ret = velawear_watchdog_start(agent);
  1053	  if (ret < 0)
  1054	    {
  1055	      agent->running = false;
  1056	      return ret;
  1057	    }
  1058	
  1059	  if (agent->audio.initialized)
  1060	    {
  1061	      ret = audio_sensor_start(&agent->audio, &agent->events);
  1062	      if (ret < 0)
  1063	        {
  1064	          agent->audio_available = false;
  1065	          syslog(LOG_WARNING,
  1066	                 "[VelaWear] Continuous microphone start failed: %d\n", ret);
  1067	        }
  1068	    }
  1069	
  1070	  if (agent->imu.initialized)
  1071	    {
  1072	      ret = pthread_create(&agent->imu_thread, NULL,
  1073	                           velawear_imu_thread, agent);
  1074	      if (ret != 0)
  1075	        {
  1076	          agent->running = false;
  1077	          syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
  1078	          return VELAWEAR_ERR_IO;
  1079	        }
  1080	      agent->imu_thread_started = true;
  1081	    }
  1082	  return VELAWEAR_OK;
  1083	}
  1084	
  1085	static void velawear_cleanup(velawear_agent_t *agent)
  1086	{
  1087	  /* Stop subsystems in reverse order */
  1088	
  1089	  agent->running = false;
  1090	  velawear_watchdog_stop(agent);
  1091	  if (agent->imu_thread_started)
  1092	    {
  1093	      pthread_join(agent->imu_thread, NULL);
  1094	      agent->imu_thread_started = false;
  1095	    }
  1096	
  1097	  audio_sensor_cleanup(&agent->audio);
  1098	  velawear_llm_cleanup(&agent->llm);
  1099	  velawear_ble_cleanup();
  1100	  imu_sensor_cleanup(&agent->imu);
  1101	  /* Stop the periodic decision worker before destroying the managers it
  1102	   * references. */
  1103	  decision_engine_cleanup(&agent->engine);
  1104	  action_manager_cleanup(&agent->actions);
  1105	  event_manager_cleanup(&agent->events);
  1106	  velawear_buttons_close();
  1107	  display_manager_cleanup(&agent->display);
  1108	  state_manager_cleanup(&agent->state_mgr);
  1109	  velawear_config_cleanup(&agent->config);
  1110	  if (agent->timer_lock_initialized)
  1111	    {
  1112	      pthread_mutex_destroy(&agent->timer_lock);
  1113	      agent->timer_lock_initialized = false;
  1114	    }
  1115	}
