  1151	    }
  1152	
  1153	  if (event->type == VELAWEAR_EVENT_VOICE_CMD)
  1154	    {
  1155	      memset(&action, 0, sizeof(action));
  1156	      action.type = VELAWEAR_ACTION_PLAY_VOICE;
