  1158	      action.params.voice.stream_id = event->data.voice.stream_id;
  1159	      action.params.voice.sample_count = event->data.voice.sample_count;
  1160	      ret = action_manager_execute(&agent->actions, &action);
  1161	      if (ret < 0)
  1162	        {
  1163	          return ret;
  1164	        }
  1165	      return action_manager_process(&agent->actions);
  1166	    }
  1167	
  1168	  if (event->type == VELAWEAR_EVENT_BLE_MSG)
  1169	    {
  1170	      return velawear_handle_agent_command(agent, event);
  1171	    }
  1172	
  1173	  if (event->type == VELAWEAR_EVENT_AUDIO)
  1174	    {
  1175	      syslog(LOG_INFO,
  1176	             "[Audio] event=%s avg_abs=%lu peak_abs=%lu active=%d\n",
  1177	             event->data.audio.text,
  1178	             (unsigned long)event->data.audio.avg_abs,
  1179	             (unsigned long)event->data.audio.peak_abs,
  1180	             event->data.audio.active ? 1 : 0);
  1181	    }
  1182	
  1183	  ret = state_manager_update_from_event(&agent->state_mgr, event);
