544	static void *velawear_watchdog_thread(void *context)
545	{
546	  velawear_agent_t *agent = (velawear_agent_t *)context;
547	  bool reported_stall = false;
548	
549	  syslog(LOG_INFO, "[Watchdog] Software monitor started\n");
550	  while (agent->running)
551	    {
552	      uint32_t age = velawear_now_ms() - agent->watchdog_last_main_ms;
553	
554	      if (age > 5000 && !reported_stall)
555	        {
556	          syslog(LOG_ERR,
557	                 "[Watchdog] Main loop heartbeat stalled (%lu ms)\n",
558	                 (unsigned long)age);
559	          reported_stall = true;
560	        }
561	      else if (age <= 5000)
562	        {
563	          reported_stall = false;
564	        }
565	
566	      usleep(1000000);
567	    }
568	
569	  syslog(LOG_INFO, "[Watchdog] Software monitor stopped\n");
570	  return NULL;
571	}
572	
573	static int velawear_watchdog_start_software(velawear_agent_t *agent)
574	{
575	  int ret;
576	
577	  agent->watchdog_last_main_ms = velawear_now_ms();
578	  ret = pthread_create(&agent->watchdog_thread, NULL,
579	                       velawear_watchdog_thread, agent);
580	  if (ret != 0)
581	    {
582	      syslog(LOG_WARNING, "[Watchdog] Software monitor start failed: %d\n",
583	             ret);
584	      return ret;
585	    }
586	
587	  agent->watchdog_thread_started = true;
588	  return VELAWEAR_OK;
589	}
