645	static void velawear_watchdog_stop(velawear_agent_t *agent)
646	{
647	  if (agent == NULL)
648	    {
649	      return;
650	    }
651	
652	  if (agent->watchdog_thread_started)
653	    {
654	      pthread_join(agent->watchdog_thread, NULL);
655	      agent->watchdog_thread_started = false;
656	    }
657	
658	  if (agent->watchdog_active && agent->watchdog_fd >= 0)
659	    {
660	      ioctl(agent->watchdog_fd, WDIOC_STOP, 0);
661	      close(agent->watchdog_fd);
662	    }
663	
664	  agent->watchdog_fd = -1;
665	  agent->watchdog_active = false;
666	}
