668	static void *velawear_imu_thread(void *context)
669	{
670	  velawear_agent_t *agent = (velawear_agent_t *)context;
671	  bool fall_reported = false;
672	  int last_motion_type = -1;
673	
674	  while (agent->running)
675	    {
676	      imu_data_t sample;
677	      motion_state_t motion;
678	      velawear_event_t event;
679	      int period_us = 20000;
680	
681	      if (imu_sensor_read(&agent->imu, &sample) == VELAWEAR_OK)
682	        {
683	          int motion_type;
684	
685	          motion = imu_sensor_get_motion_state(&agent->imu);
686	          motion_type = motion.is_running ? 2 :
687	                        (motion.is_moving ? 1 : 0);
688	
689	          memset(&event, 0, sizeof(event));
690	          event.type = VELAWEAR_EVENT_MOTION;
691	          event.priority = VELAWEAR_PRIORITY_NORMAL;
692	          event.timestamp = sample.timestamp;
693	          event.data.motion.motion_type = motion_type;
694	          event.data.motion.intensity = motion.motion_intensity;
695	
696	          if (motion_type != last_motion_type)
697	            {
698	              const char *motion_name = motion_type == 2 ? "跑步" :
699	                                        (motion_type == 1 ? "活动" : "静止");
700	              syslog(LOG_INFO, "[MVP] IMU state=%s intensity=%.2f\n",
701	                     motion_name, motion.motion_intensity);
702	              velawear_ble_update_motion(motion_type,
703	                                         motion.motion_intensity);
704	              /* 活动恢复时清除 BLE 告警状态。 */
705	              if (last_motion_type == 0 && motion_type != 0)
706	                {
707	                  velawear_ble_set_alert(false);
708	                }
709	              last_motion_type = motion_type;
710	
711	              /* Motion state is edge-triggered for the event queue.  The IMU
712	               * still samples at its configured rate for fall detection, but
713	               * repeated identical states must not consume all MQ objects. */
714	              if (event_manager_push(&agent->events, &event) < 0)
715	                {
716	                  syslog(LOG_WARNING,
717	                         "[VelaWear] Failed to queue motion event\n");
718	                }
719	            }
720	
721	          if (motion.fall_detected && !fall_reported)
722	            {
723	              event.type = VELAWEAR_EVENT_FALL;
724	              event.priority = VELAWEAR_PRIORITY_CRITICAL;
725	              if (event_manager_push(&agent->events, &event) < 0)
726	                {
727	                  syslog(LOG_WARNING,
728	                         "[VelaWear] Failed to queue fall event\n");
729	                }
730	              fall_reported = true;
731	            }
732	          else if (!motion.fall_detected)
733	            {
734	              fall_reported = false;
735	            }
736	        }
737	
738	      if (agent->config.imu_sample_rate_hz > 0)
739	        {
740	          period_us = 1000000 / agent->config.imu_sample_rate_hz;
741	          if (period_us < 1000)
742	            {
743	              period_us = 1000;
744	            }
745	        }
746	
747	      usleep(period_us);
748	    }
749	
750	  return NULL;
751	}
