   351	  velawear_state_t state;
   352	  velawear_event_t event;
   353	
   354	  syslog(LOG_INFO, "[Decision] Thread started\n");
   355	
   356	  while (engine->running)
   357	    {
   358	      usleep(100000);  /* 100ms */
   359	
   360	      if (engine->state_mgr != NULL)
   361	        {
   362	          memset(&event, 0, sizeof(event));
   363	          state = state_manager_get_state(engine->state_mgr);
   364	          event.type = VELAWEAR_EVENT_TIMER;
   365	          event.priority = VELAWEAR_PRIORITY_NORMAL;
   366	          event.timestamp = (uint32_t)time(NULL);
   367	          event.data.timer.id = 0;
   368	          (void)decision_engine_evaluate(engine, &state, &event);
