   502	                             int layer,
   503	                             uint32_t priority,
   504	                             rule_condition_t condition,
   505	                             rule_action_t action,
   506	                             void *context)
   507	{
   508	  pthread_mutex_lock(&engine->lock);
   509	
   510	  if (engine->rule_count >= DECISION_RULES_MAX)
   511	    {
   512	      pthread_mutex_unlock(&engine->lock);
   513	      return VELAWEAR_ERR_NOMEM;
   514	    }
   515	
   516	  decision_rule_t *rule = &engine->rules[engine->rule_count];
   517	  rule->id = engine->rule_count;
   518	  strncpy(rule->name, name, sizeof(rule->name) - 1);
   519	  rule->layer = layer;
   520	  rule->priority = priority;
   521	  rule->condition = condition;
   522	  rule->action = action;
   523	  rule->context = context;
   524	  rule->enabled = true;
   525	
   526	  engine->rule_count++;
   527	
   528	  pthread_mutex_unlock(&engine->lock);
   529	
   530	  syslog(LOG_INFO, "[Decision] Added rule '%s' (layer=%d, priority=%lu)\n",
   531	         name, layer, (unsigned long)priority);
