   553	int decision_engine_evaluate(velawear_engine_t *engine,
   554	                             velawear_state_t *state,
   555	                             velawear_event_t *event)
   556	{
   557	  int ret;
   558	
   559	  if (engine == NULL || state == NULL || event == NULL)
   560	    {
   561	      return VELAWEAR_ERR_INVAL;
   562	    }
   563	
   564	  pthread_mutex_lock(&engine->lock);
   565	
   566	  for (int i = 0; i < engine->rule_count; i++)
   567	    {
   568	      if (!engine->rules[i].enabled)
   569	        {
   570	          continue;
   571	        }
   572	
   573	      if (engine->rules[i].condition &&
   574	          engine->rules[i].condition(state, event,
   575	                                     engine->rules[i].context))
   576	        {
   577	          ret = engine->rules[i].action(state, engine->rules[i].context);
   578	          if (ret < 0)
   579	            {
   580	              syslog(LOG_WARNING,
   581	                     "[Decision] Rule '%s' action failed: %d\n",
   582	                     engine->rules[i].name, ret);
   583	            }
   584	
   585	          /* For emergency rules, stop after first match */
   586	
   587	          if (engine->rules[i].layer == 0)
   588	            {
   589	              pthread_mutex_unlock(&engine->lock);
   590	              return engine->rules[i].id;
   591	            }
   592	        }
   593	    }
   594	
   595	  pthread_mutex_unlock(&engine->lock);
   596	
