   202	  actions->handlers[actions->handler_count].action_type = action_type;
   203	  actions->handlers[actions->handler_count].handler = handler;
   204	  actions->handlers[actions->handler_count].context = context;
   205	  actions->handler_count++;
   206	
   207	  pthread_mutex_unlock(&actions->lock);
   208	
   209	  syslog(LOG_INFO, "[ActionMgr] Registered handler for type %d\n",
   210	         action_type);
   211	  return VELAWEAR_OK;
   212	}
