254	      syslog(LOG_ERR, "[AudioStream] level worker start failed: %d\n", ret);
255	      return VELAWEAR_ERR_IO;
256	    }
257	
258	  audio->thread_started = true;
259	  return VELAWEAR_OK;
260	}
