276	  velawear_mic_stream_stop();
277	  if (audio->fd >= 0)
278	    {
279	      close(audio->fd);
280	      audio->fd = -1;
281	    }
282	
283	  audio->events = NULL;
284	  audio->initialized = false;
285	  syslog(LOG_INFO, "[Audio] Cleaned up\n");
286	}

