297	static uint32_t audio_crc32_update(uint32_t crc, const uint8_t *data,
298	                                   size_t length)
299	{
300	  size_t i;
301	
302	  for (i = 0; i < length; i++)
303	    {
304	      uint32_t bit;
305	
306	      crc ^= data[i];
307	      for (bit = 0; bit < 8; bit++)
308	        {
309	          crc = (crc & 1U) != 0U ?
310	                (crc >> 1) ^ 0xedb88320U : crc >> 1;
311	        }
312	    }
313	
314	  return crc;
315	}
