337	static int audio_mic_stream_start_locked(void)
338	{
339	  AUDCODEC_ADCCfgTypeDef adc_cfg;
340	  int ret;
341	  bool codec_initialized = false;
342	
343	  if (g_mic_stream_active)
344	    {
345	      return 0;
346	    }
347	
348	  memset(&g_mic_stream_codec, 0, sizeof(g_mic_stream_codec));
349	  memset(&g_mic_stream_dma, 0, sizeof(g_mic_stream_dma));
350	  memset(&adc_cfg, 0, sizeof(adc_cfg));
351	
352	  g_mic_stream_codec.Instance = hwp_audcodec;
353	  g_mic_stream_codec.Init.adc_cfg.opmode = 1;
354	  g_mic_stream_codec.hdma[HAL_AUDCODEC_ADC_CH0] = &g_mic_stream_dma;
355	  g_mic_stream_dma.Instance = DMA1_Channel1;
356	  g_mic_stream_dma.Init.Request = DMA_REQUEST_39;
357	
358	  HAL_PMU_EnableAudio(1);
359	  HAL_RCC_EnableModule(RCC_MOD_AUDCODEC);
360	  ret = HAL_AUDCODEC_Init(&g_mic_stream_codec);
361	  if (ret != HAL_OK)
362	    {
363	      goto fail_power;
364	    }
365	  codec_initialized = true;
366	
367	  HAL_TURN_ON_PLL();
368	  adc_cfg.opmode = 1;
369	  adc_cfg.adc_clk = (AUDCODE_ADC_CLK_CONFIG_TYPE *)&g_adc_clock;
370	  ret = HAL_AUDCODEC_Config_RChanel(&g_mic_stream_codec, 0, &adc_cfg);
371	  if (ret != HAL_OK)
372	    {
373	      goto fail_codec;
374	    }
375	
376	  ret = HAL_AUDCODEC_Config_ADCPath_Volume(&g_mic_stream_codec, 0, AUDIO_MIC_ADC_GAIN_DB);
377	  if (ret != HAL_OK)
378	    {
379	      goto fail_codec;
380	    }
381	
382	  HAL_AUDCODEC_Config_Analog_ADCPath(
383	      (AUDCODE_ADC_CLK_CONFIG_TYPE *)&g_adc_clock);
384	  __HAL_AUDCODEC_ADC_ENABLE(&g_mic_stream_codec);
385	
386	  ret = audio_dma_attach_irqs();
387	  if (ret < 0)
388	    {
389	      syslog(LOG_ERR, "[AudioStream] DMA IRQ attach failed: %d\n", ret);
390	      goto fail_adc;
391	    }
392	
393	  memset(g_mic_stream_buffer, 0, sizeof(g_mic_stream_buffer));
394	  g_mic_stream_ready = 0;
395	  g_mic_stream_error = false;
396	  g_mic_stream_codec_ref = &g_mic_stream_codec;
397	  ret = HAL_AUDCODEC_Receive_DMA(
398	      &g_mic_stream_codec, (uint8_t *)g_mic_stream_buffer,
399	      sizeof(g_mic_stream_buffer), HAL_AUDCODEC_ADC_CH0);
400	  if (ret != HAL_OK)
401	    {
402	      g_mic_stream_codec_ref = NULL;
403	      syslog(LOG_ERR, "[AudioStream] ADC DMA start failed: %d\n", ret);
404	      goto fail_adc;
405	    }
406	
407	  g_mic_stream_active = true;
408	  syslog(LOG_INFO,
409	         "[AudioStream] continuous MEMS capture started (%d Hz, half=%d samples)\n",
410	         AUDIO_TEST_RATE, AUDIO_MIC_STREAM_HALF_WORDS);
411	  return 0;
412	
413	fail_adc:
414	  audio_adc_stop(&g_mic_stream_codec);
415	fail_codec:
416	  if (codec_initialized)
417	    {
418	      HAL_AUDCODEC_DeInit(&g_mic_stream_codec);
419	      HAL_TURN_OFF_PLL();
420	    }
421	fail_power:
422	  HAL_RCC_DisableModule(RCC_MOD_AUDCODEC);
423	  HAL_PMU_EnableAudio(0);
424	  return -1;
425	}
