427	static void audio_mic_stream_stop_locked(void)
428	{
429	  if (!g_mic_stream_active && g_mic_stream_codec_ref == NULL)
430	    {
431	      return;
432	    }
433	
434	  /* Hide the codec from ISR callbacks before aborting the DMA channel. */
435	  g_mic_stream_active = false;
436	  g_mic_stream_codec_ref = NULL;
437	  g_mic_stream_ready = 0;
438	  audio_adc_stop(&g_mic_stream_codec);
439	  HAL_AUDCODEC_DeInit(&g_mic_stream_codec);
440	  HAL_TURN_OFF_PLL();
441	  HAL_RCC_DisableModule(RCC_MOD_AUDCODEC);
442	  HAL_PMU_EnableAudio(0);
443	  syslog(LOG_INFO, "[AudioStream] continuous MEMS capture stopped\n");
444	}
