463	int velawear_mic_stream_read_level(uint32_t *avg_abs, uint32_t *peak_abs)
464	{
465	  uint8_t ready;
466	  uint32_t offset;
467	  uint64_t sum_abs = 0;
468	  uint32_t peak = 0;
469	  irqstate_t flags;
470	
471	  if (avg_abs == NULL || peak_abs == NULL)
472	    {
473	      return -1;
474	    }
475	
476	  pthread_mutex_lock(&g_audio_hw_lock);
477	  if (!g_mic_stream_active)
478	    {
479	      pthread_mutex_unlock(&g_audio_hw_lock);
480	      return 0;
481	    }
482	
483	  flags = up_irq_save();
484	  if (g_mic_stream_error)
485	    {
486	      up_irq_restore(flags);
487	      pthread_mutex_unlock(&g_audio_hw_lock);
488	      return -1;
489	    }
490	
491	  ready = g_mic_stream_ready;
492	  if (ready & 1U)
493	    {
494	      g_mic_stream_ready &= (uint8_t)~1U;
495	      offset = 0;
496	    }
497	  else if (ready & 2U)
498	    {
499	      g_mic_stream_ready &= (uint8_t)~2U;
500	      offset = AUDIO_MIC_STREAM_HALF_WORDS;
501	    }
502	  else
503	    {
504	      up_irq_restore(flags);
505	      pthread_mutex_unlock(&g_audio_hw_lock);
506	      return 0;
507	    }
508	  up_irq_restore(flags);
509	
510	  for (uint32_t i = 0; i < AUDIO_MIC_STREAM_HALF_WORDS; i++)
511	    {
512	      int32_t sample = (int16_t)(g_mic_stream_buffer[offset + i] & 0xffff);
513	      uint32_t magnitude = (uint32_t)(sample < 0 ? -sample : sample);
514	
515	      sum_abs += magnitude;
516	      if (magnitude > peak)
517	        {
518	          peak = magnitude;
519	        }
520	    }
521	
522	  *avg_abs = (uint32_t)(sum_abs / AUDIO_MIC_STREAM_HALF_WORDS);
523	  *peak_abs = peak;
524	  pthread_mutex_unlock(&g_audio_hw_lock);
525	  return 1;
526	}
