542	static int audio_speaker_alert(int duration_ms, int pattern)
543	{
544	  AUDCODEC_HandleTypeDef codec;
545	  DMA_HandleTypeDef *dma = &g_audio_dma;
546	  AUDCODEC_DACCfgTypeDef dac_cfg;
547	  uint32_t samples;
548	  uint32_t i;
549	  uint32_t waited;
550	  int ret = HAL_OK;
551	
552	  if (duration_ms <= 0)
553	    {
554	      return -1;
555	    }
556	
557	  memset(&codec, 0, sizeof(codec));
558	  memset(dma, 0, sizeof(*dma));
559	  memset(&dac_cfg, 0, sizeof(dac_cfg));
560	  codec.Instance = hwp_audcodec;
561	  codec.Init.dac_cfg.opmode = 1;
562	  codec.hdma[HAL_AUDCODEC_DAC_CH0] = dma;
563	  dma->Instance = DMA1_Channel1;
564	  dma->Init.Request = DMA_REQUEST_41;
565	
566	  samples = (uint32_t)(((uint64_t)AUDIO_TEST_RATE * duration_ms) / 1000);
567	  if (samples == 0 || samples > AUDIO_DMA_BUFFER_WORDS)
568	    {
569	      return -1;
570	    }
571	
572	  for (i = 0; i < samples; i++)
573	    {
574	      uint32_t elapsed_ms = (i * 1000U) / AUDIO_TEST_RATE;
575	      uint32_t phase_ms = elapsed_ms % 1000U;
576	      bool audible = pattern != 8 ||
577	                     phase_ms < 120U ||
578	                     (phase_ms >= 200U && phase_ms < 320U) ||
579	                     (phase_ms >= 400U && phase_ms < 520U);
580	      g_audio_dma_buffer[i] = audible ?
581	        (uint32_t)(uint16_t)g_tone[i & 31] : 0;
582	    }
583	
584	  syslog(LOG_INFO, "[AudioAlert] begin (%d ms, pattern=%d)\n",
585	         duration_ms, pattern);
586	  HAL_PMU_EnableAudio(1);
587	  HAL_RCC_EnableModule(RCC_MOD_AUDCODEC);
588	  ret = HAL_AUDCODEC_Init(&codec);
589	  if (ret != HAL_OK)
590	    {
591	      goto cleanup_power;
592	    }
593	
594	  dac_cfg.opmode = 1;
595	  dac_cfg.dac_clk = (AUDCODE_DAC_CLK_CONFIG_TYPE *)&g_dac_clock;
596	  ret = HAL_AUDCODEC_Config_TChanel(&codec, 0, &dac_cfg);
597	  if (ret != HAL_OK)
598	    {
599	      goto cleanup_codec;
600	    }
601	
602	  __HAL_AUDCODEC_DAC_ENABLE(&codec);
603	  ret = HAL_AUDCODEC_Config_DACPath_Volume(&codec, 0, AUDIO_ALERT_DAC_VOLUME);
604	  if (ret != HAL_OK)
605	    {
606	      goto cleanup_dac;
607	    }
608	
609	  HAL_AUDCODEC_Config_DACPath(&codec, 1);
610	  HAL_TURN_ON_PLL();
611	  ret = HAL_AUDCODEC_Config_Analog_DACPath(
612	          (AUDCODE_DAC_CLK_CONFIG_TYPE *)&g_dac_clock);
613	  if (ret != HAL_OK)
614	    {
615	      goto cleanup_dac;
616	    }
617	
618	  ret = audio_dma_attach_irqs();
619	  if (ret < 0)
620	    {
621	      syslog(LOG_ERR, "[AudioAlert] DMA IRQ attach failed: %d\n", ret);
622	      goto cleanup_dac;
623	    }
624	
625	  g_audio_dma_codec = &codec;
626	  g_audio_dma_complete = false;
627	  g_audio_dma_error = false;
628	  ret = HAL_AUDCODEC_Transmit_DMA(
629	          &codec, (uint8_t *)g_audio_dma_buffer, samples * sizeof(uint32_t),
630	          HAL_AUDCODEC_DAC_CH0);
631	  if (ret != HAL_OK)
632	    {
633	      syslog(LOG_ERR, "[AudioAlert] DMA start failed: %d\n", ret);
634	      g_audio_dma_codec = NULL;
635	      goto cleanup_dac;
636	    }
637	
638	#if VELAWEAR_ENABLE_EXTERNAL_PA
639	  audio_pa_set(true);
640	#else
641	  audio_pa_set(false);
642	  syslog(LOG_WARNING,
643	         "[AudioAlert] external PA disabled after reset-safe HIL\n");
644	#endif
645	  HAL_Delay_us(30000);
646	  HAL_AUDCODEC_Config_DACPath(&codec, 0);
647	
648	  for (waited = 0; waited < (uint32_t)duration_ms + 500U; waited++)
649	    {
650	      if (g_audio_dma_complete || g_audio_dma_error)
651	        {
652	          break;
653	        }
654	      usleep(1000);
655	    }
656	  if (!g_audio_dma_complete || g_audio_dma_error)
657	    {
658	      ret = g_audio_dma_error ? HAL_ERROR : HAL_TIMEOUT;
659	      syslog(LOG_WARNING, "[AudioAlert] DMA %s after %lu ms\n",
660	             g_audio_dma_error ? "error" : "timeout",
661	             (unsigned long)waited);
662	    }
663	  else
664	    {
665	      syslog(LOG_INFO, "[AudioAlert] DMA complete\n");
666	    }
667	  g_audio_dma_codec = NULL;
668	
669	  audio_pa_set(false);
670	  syslog(LOG_INFO, "[AudioAlert] tone DMA complete\n");
671	
672	cleanup_dac:
673	  audio_dac_stop(&codec);
674	cleanup_codec:
675	  HAL_AUDCODEC_DeInit(&codec);
676	  HAL_TURN_OFF_PLL();
677	cleanup_power:
678	  HAL_PMU_EnableAudio(0);
679	  syslog(ret == HAL_OK ? LOG_INFO : LOG_WARNING,
680	         "[AudioAlert] speaker alert %s (%d ms, pattern=%d)\n",
681	         ret == HAL_OK ? "played" : "failed", duration_ms, pattern);
682	  return ret == HAL_OK ? 0 : -1;
683	}
