  1091	void display_manager_tick(velawear_display_t *display)
  1092	{
  1093	  uint32_t now;
  1094	  velawear_state_t state;
  1095	  lv_obj_t *alert_label;
  1096	
  1097	  if (display == NULL || !display->initialized)
  1098	    {
  1099	      return;
  1100	    }
  1101	
  1102	  now = display_now_ms();
  1103	  display_audio_poll(display);
  1104	  pthread_mutex_lock(&display->lock);
  1105	  if (display->alert_pending)
  1106	    {
  1107	      lv_obj_set_style_bg_color(lv_screen_active(), lv_color_hex(0x5b1111), 0);
  1108	      lv_label_set_text(display->status_label, "主动提醒");
  1109	      lv_obj_set_style_text_color(display->status_label,
  1110	                                  lv_color_hex(0xfca5a5), 0);
  1111	      alert_label = display->detail_active ? display->metrics_label :
  1112	                    display->page_content[0];
  1113	      if (alert_label != NULL)
  1114	        {
  1115	          lv_label_set_text(alert_label, display->pending_alert);
  1116	          lv_obj_set_style_text_color(alert_label,
  1117	                                      lv_color_hex(UI_TEXT_COLOR), 0);
  1118	        }
  1119	      if (g_alert_message != NULL && g_alert_overlay != NULL)
  1120	        {
  1121	          lv_label_set_text(g_alert_message, display->pending_alert);
  1122	          lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1123	          lv_obj_move_foreground(g_alert_overlay);
  1124	        }
  1125	      display->alert_until_ms = now + 60000;
  1126	      display->alert_active = true;
  1127	      syslog(LOG_INFO,
  1128	             "[Display] Alert consumed page=%u detail=%d label=%p hold=60000ms text=%s\n",
  1129	             (unsigned int)display->page_index, display->detail_active ? 1 : 0,
  1130	             alert_label, display->pending_alert);
  1131	      display->alert_pending = false;
  1132	    }
  1133	  pthread_mutex_unlock(&display->lock);
  1134	
  1135	  if (display->alert_active)
  1136	    {
  1137	      if (now < display->alert_until_ms)
  1138	        {
  1139	          lv_timer_handler();
  1140	          return;
  1141	        }
  1142	
  1143	      display->alert_active = false;
  1144	      syslog(LOG_INFO, "[Display] Alert expired\n");
  1145	      if (g_alert_overlay != NULL)
  1146	        {
  1147	          lv_obj_add_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1148	        }
  1149	      display_restore_theme(display);
  1150	      display->last_update_ms = 0;
  1151	    }
  1152	
  1153	  if (display->last_update_ms == 0 || now - display->last_update_ms >=
  1154	      (display->active_app == VELAWEAR_APP_STOPWATCH &&
  1155	       display->stopwatch_running ? 100 : 250))
  1156	    {
  1157	      state = state_manager_get_state(display->state_mgr);
  1158	      if (display->detail_active)
  1159	        {
  1160	          display_render_app(display, &state);
  1161	        }
  1162	      else
  1163	        {
  1164	          display_render_top(display, &state);
  1165	        }
  1166	      display->last_update_ms = now;
  1167	    }
  1168	
  1169	  lv_timer_handler();
  1170	}
